import sys
import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
        except StopIteration:
            break

        if N == 3:
            results.append("2 3 6")
            continue

        A = []
        LCM_VAL = 1
        primes = []

        temp = 2
        while len(primes) < N:
            is_prime = True
            for p in primes:
                if p * p > temp:
                    break
                if temp % p == 0:
                    is_prime = False
                    break
            if is_prime:
                primes.append(temp)
            temp += 1

        primes = primes[:N]

        for i in range(N):
            val = primes[i]
            A.append(val)
            LCM_VAL *= val

        if LCM_VAL > 10**18:
            pass

        A[N-1] = LCM_VAL

        results.append(" ".join(map(str, A)))

    print("\n".join(results))

if __name__ == "__main__":
    solve()
